// Avoid for dynamic lists
{users.map((user, index) => (
  <User key={index} user={user} />
))}

// Better
{users.map((user) => (
  <User key={user.id} user={user} />
))}

// Problematic: random key changes on every render
{users.map((user) => (
  <User key={Math.random()} user={user} />
))}

// Better: stable key
{users.map((user) => (
  <User key={user.id} user={user} />
))}

const users = [
  { id: 1, name: "Jeet" },
  { id: 1, name: "Rahul" }
];

// Incorrect because both siblings have the same key
{users.map((user) => (
  <p key={user.id}>{user.name}</p>
))}

// Before
// [{ id: 1, name: "A" }, { id: 2, name: "B" }]

// After adding a new item at the beginning
// [{ id: 3, name: "C" }, { id: 1, name: "A" }, { id: 2, name: "B" }]

// React uses the stable IDs to identify A and B.

const colors = ["Red", "Green", "Blue"];

function ColorList() {
  return (
    <ul>
      {colors.map((color, index) => (
        <li key={index}>{color}</li>
      ))}
    </ul>
  );
}

